mapper.select:
SELECT COUNT(*) FROM afv_remote_generation_job j JOIN afv_generation_submission s ON s.id = j.submission_id
WHERE s.kind = #{kind} AND s.task_id = #{taskId}
    AND (j.permit_held = TRUE OR j.state NOT IN ('SUCCEEDED','PARTIAL_FAILED','FAILED','CANCELLED'))

SELECT id, request_hash, kind FROM afv_generation_submission
WHERE scope_key = #{scope}
    AND agent_invocation_key = SHA2(CAST(JSON_ARRAY(#{agentRunId}, #{toolCallId}) AS CHAR CHARACTER SET utf8mb4), 256)
